import React, { useEffect, useState } from 'react';
import { fetchLogById } from '../../api/LogsApi';

function LogDetailModal({ logId, log, onClose, onDelete }) {
  // 하위호환: 기존처럼 log 객체만 넘겨도 동작
  const initialId = logId || log?.id || null;

  const [detail, setDetail] = useState(log || null);
  const [loading, setLoading] = useState(Boolean(initialId));
  const [error, setError] = useState(null);

  const [deleting, setDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState(null);

  useEffect(() => {
    const run = async () => {
      if (!initialId) {
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError(null);

        const res = await fetchLogById(initialId);
        setDetail(res || null);
      } catch (e) {
        setError(e);
        // fallback: 목록에서 넘어온 log라도 보여주기
        setDetail(log || null);
      } finally {
        setLoading(false);
      }
    };

    run();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialId]);

  const data = detail;

  const handleDeleteClick = async () => {
    if (!initialId || !onDelete) return;

    try {
      setDeleting(true);
      setDeleteError(null);
      await onDelete(initialId); // ✅ 부모(LogsPage)의 단건 삭제 로직 재사용
      onClose?.();               // ✅ 삭제 성공하면 모달 닫기
    } catch (e) {
      setDeleteError(e);
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <h2>로그 상세</h2>

        {loading && <p>상세 정보를 불러오는 중...</p>}

        {!loading && error && (
          <p style={{ color: 'red' }}>
            상세 조회 실패: {error.message}
            <br />
            (가능하면 목록에서 받은 요약 정보로 표시합니다)
          </p>
        )}

        {!loading && !data && <p>표시할 상세 데이터가 없습니다.</p>}

        {!loading && data && (
          <div style={{ marginTop: 12 }}>
            <p><strong>ID:</strong> {data.id}</p>
            <p><strong>수집 시각:</strong> {data.collectedAt || '-'}</p>
            <p><strong>이벤트 타입:</strong> {data.eventType || '-'}</p>
            <p><strong>파일 경로:</strong> {data.path || '-'}</p>
            <p><strong>파일 크기:</strong> {data.size != null ? data.size : '-'}</p>
            <p><strong>엔트로피:</strong> {data.entropy != null ? data.entropy : '-'}</p>
            <p><strong>해시:</strong> {data.hash || '-'}</p>

            <hr style={{ margin: '12px 0' }} />

            <p><strong>AI 라벨:</strong> {data.aiLabel || '-'}</p>
            <p><strong>AI 점수:</strong> {data.aiScore != null ? data.aiScore : '-'}</p>

            <p style={{ marginTop: 10 }}><strong>AI 상세:</strong></p>
            <pre style={{ whiteSpace: 'pre-wrap' }}>
              {data.aiDetail || '(AI 상세 없음)'}
            </pre>
          </div>
        )}

        {deleteError && (
          <p style={{ color: 'red', marginTop: 8 }}>
            삭제 실패: {deleteError.message}
          </p>
        )}

        {/* ✅ 하단 버튼 영역 */}
        <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 12 }}>
          <button className="btn" onClick={onClose} disabled={deleting}>
            닫기
          </button>

          <button
            className="btn"
            onClick={handleDeleteClick}
            disabled={!initialId || !onDelete || deleting}
            title={!onDelete ? '삭제 핸들러가 연결되지 않았습니다.' : '이 로그 삭제'}
          >
            {deleting ? '삭제 중...' : '삭제'}
          </button>
        </div>
      </div>
    </div>
  );
}

export default LogDetailModal;
